getPSControlLogics.scriptCode:
const actionTag = args.tag;
const wizardPanel = view.getCtrl('WIZARDPANEL', 'wizardpanel');
if(actionTag === "beforeUpload"){
    ctrl.startLoading();
    if(wizardPanel && wizardPanel.state.buttonsState && wizardPanel.state.buttonsState["file_selection@NEXT"]){
        wizardPanel.state.buttonsState["file_selection@NEXT"].disabled = true; 
    }
}
if(actionTag === "onSuccess" || actionTag === "onError"){
    ctrl.endLoading();
    if(wizardPanel && wizardPanel.state.buttonsState && wizardPanel.state.buttonsState["file_selection@NEXT"]){
        wizardPanel.state.buttonsState["file_selection@NEXT"].disabled = false; 
    }
}

getPSDEFormItemUpdates.scriptCode:
console.log("change_page",data);
let selection_page_names = data.selection_page_names;
let pages = selection_page_names.split(',').map(item => item.trim()).map(value => {
    return {
        ai_kb_doc_name: value
    };
});
data.selected_page_name=pages;

let file_ids=[];
let files =[];
if(data.selection_file_ids){
    file_ids = JSON.parse(data.selection_file_ids);
    files = file_ids.map(file => {
    // const file_name =file.name.split('.')[0];   
    const dot_index = file.name.lastIndexOf('.');
    const file_name = dot_index !== -1 ? file.name.substring(0, dot_index) : file.name;
    return {
        ai_kb_doc_name2: file_name,
        file_size: file.size
        };
    });

    return {
        selection_file_ids: data.selection_file_ids,
        selected_file_name: files 
        }
}

